import random, time
from typing import Iterable

ALLOWED_CALLERS = {
    'spiffe://prod.mesh/ns/orders/sa/checkout',
    'spiffe://prod.mesh/ns/billing/sa/reconciler',
}

def authorize_spiffe_peer(san_uris: Iterable[str], expected_domain: str = 'prod.mesh') -> str:
    for uri in san_uris:
        if not uri.startswith(f'spiffe://{expected_domain}/'):
            continue
        if uri in ALLOWED_CALLERS:
            return uri
    raise PermissionError('Peer SPIFFE ID not authorized for this service')

