def fetch_svid_with_backoff(workload_client, max_retries: int = 3):
    for attempt in range(max_retries):
        try:
            return workload_client.fetch_x509_svid(timeout=2.0)
        except ConnectionError as exc:
            if attempt == max_retries - 1:
                raise RuntimeError('SPIRE Agent UDS unavailable; failing closed') from exc
            time.sleep((0.25 * (2 ** attempt)) + random.uniform(0, 0.1))
